//! Loading character packages from disk and serving their assets.
//!
//! A character package is a directory with `manifest.json`, `spritesheet.png`
//! and `preview.png`. Packages live under `~/shimeji/characters/<id>/`.
//! The bundled "Block Cat" is embedded in the binary and written out on first
//! run so the app works end-to-end with zero setup.

use base64::Engine;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

// Embedded builtin characters (generated by scripts/gen-characters.mjs), written
// to disk on first run so the app works end-to-end with zero setup.
struct Builtin {
    id: &'static str,
    manifest: &'static str,
    sheet: &'static [u8],
    preview: &'static [u8],
}

macro_rules! builtin {
    ($id:literal) => {
        Builtin {
            id: $id,
            manifest: include_str!(concat!("../../characters/", $id, "/manifest.json")),
            sheet: include_bytes!(concat!("../../characters/", $id, "/spritesheet.png")),
            preview: include_bytes!(concat!("../../characters/", $id, "/preview.png")),
        }
    };
}

const BUILTINS: &[Builtin] = &[
    builtin!("coder-cat"),
    builtin!("roaster"),
    builtin!("love-guru"),
    builtin!("thief"),
];

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AnimationDef {
    pub row: u32,
    pub frames: u32,
    #[serde(rename = "loop")]
    pub loops: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BehaviorConfig {
    pub gravity: f64,
    pub walk_speed: f64,
    pub climb_speed: f64,
    pub can_climb: bool,
    pub can_sit: bool,
    pub sit_chance: f64,
    pub turn_chance: f64,
    #[serde(default)]
    pub speak_chance: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CharacterManifest {
    pub id: String,
    pub name: String,
    pub author: String,
    pub version: String,
    #[serde(default)]
    pub personality: String,
    pub frame_width: u32,
    pub frame_height: u32,
    pub fps: f64,
    pub scale: f64,
    pub animations: HashMap<String, AnimationDef>,
    pub behaviors: BehaviorConfig,
}

/// `~/shimeji`
pub fn shimeji_root(home: &Path) -> PathBuf {
    home.join("shimeji")
}

/// `~/shimeji/characters`
pub fn characters_dir(home: &Path) -> PathBuf {
    shimeji_root(home).join("characters")
}

/// Write any embedded builtin characters that aren't installed yet.
pub fn ensure_builtin_characters(home: &Path) -> std::io::Result<()> {
    for b in BUILTINS {
        let dir = characters_dir(home).join(b.id);
        if dir.join("manifest.json").exists() {
            continue;
        }
        fs::create_dir_all(&dir)?;
        fs::write(dir.join("manifest.json"), b.manifest)?;
        fs::write(dir.join("spritesheet.png"), b.sheet)?;
        fs::write(dir.join("preview.png"), b.preview)?;
    }
    Ok(())
}

fn parse_manifest(path: &Path) -> Option<CharacterManifest> {
    let text = fs::read_to_string(path).ok()?;
    match serde_json::from_str::<CharacterManifest>(&text) {
        Ok(m) => Some(m),
        Err(e) => {
            eprintln!("invalid manifest at {}: {e}", path.display());
            None
        }
    }
}

/// Read every subdirectory of `~/shimeji/characters` and return valid manifests.
pub fn load_characters(home: &Path) -> Vec<CharacterManifest> {
    let dir = characters_dir(home);
    let mut out = Vec::new();
    let Ok(entries) = fs::read_dir(&dir) else {
        return out;
    };
    for entry in entries.flatten() {
        let p = entry.path();
        if p.is_dir() {
            let manifest = p.join("manifest.json");
            if manifest.exists() {
                if let Some(m) = parse_manifest(&manifest) {
                    out.push(m);
                }
            }
        }
    }
    out.sort_by(|a, b| a.name.cmp(&b.name));
    out
}

fn png_base64(path: &Path) -> Result<String, String> {
    let bytes = fs::read(path).map_err(|e| format!("read {}: {e}", path.display()))?;
    Ok(base64::engine::general_purpose::STANDARD.encode(bytes))
}

/// A character's spritesheet PNG as a base64 string (for the webview to turn
/// into an ImageBitmap without asset-protocol scope juggling).
pub fn spritesheet_base64(home: &Path, id: &str) -> Result<String, String> {
    png_base64(&characters_dir(home).join(id).join("spritesheet.png"))
}

/// A character's preview thumbnail PNG as a base64 string.
pub fn preview_base64(home: &Path, id: &str) -> Result<String, String> {
    png_base64(&characters_dir(home).join(id).join("preview.png"))
}

/// Remove an installed character package from disk.
pub fn delete_character(home: &Path, id: &str) -> Result<(), String> {
    let dir = characters_dir(home).join(id);
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| format!("delete {}: {e}", dir.display()))?;
    }
    Ok(())
}

// ----- active set persistence (~/shimeji/active.json) --------------------

fn active_path(home: &Path) -> PathBuf {
    shimeji_root(home).join("active.json")
}

/// The list of character ids that should be running, in spawn order. `None` if
/// the file doesn't exist yet (first run).
pub fn read_active(home: &Path) -> Option<Vec<String>> {
    let text = fs::read_to_string(active_path(home)).ok()?;
    serde_json::from_str(&text).ok()
}

pub fn write_active(home: &Path, ids: &[String]) {
    let _ = fs::create_dir_all(shimeji_root(home));
    if let Ok(text) = serde_json::to_string_pretty(ids) {
        let _ = fs::write(active_path(home), text);
    }
}
